    grid-template-columns: 1fr 2fr;
    gap: var(--spacing-3xl);
    margin-bottom: var(--spacing-3xl);
}

.footer-logo {
    font-size: 1.5rem;
    font-weight: 700;
    color: white;
    display: inline-block;
    margin-bottom: var(--spacing-md);
