    grid-template-columns: repeat(3, 1fr);
    gap: var(--spacing-xl);
}

.footer-column h3 {
    color: white;
    font-size: 1rem;
    margin-bottom: var(--spacing-lg);
}

.footer-column ul {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
}

.footer-bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: var(--spacing-xl);
    border-top: 1px solid var(--color-primary-light);
    font-size: 0.875rem;
    color: #9ca3af;
}

.footer-bottom p {
