        display: none;
        position: absolute;
        top: 100%;
        left: 0;
        right: 0;
        background: white;
        padding: var(--spacing-md);
        border-bottom: 1px solid var(--color-border);
        box-shadow: 0 4px 6px -1px rgba(0,0,0,0.1);
    }

    .main-nav.active {
        display: block;
    }

    .main-nav ul {
        flex-direction: column;
        gap: var(--spacing-md);
    }

    .search-form {
        display: none; 
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .newsletter-container {
        grid-template-columns: 1fr;
        text-align: center;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }

    .footer-nav {
        grid-template-columns: 1fr;
    }

    .footer-bottom {
        flex-direction: column;
        gap: var(--spacing-md);
        text-align: center;
    }
}
