document.addEventListener('DOMContentLoaded', () => {
    // Mobile menu toggle
    const menuToggle = document.querySelector('.menu-toggle');
    const mainNav = document.getElementById('main-nav');

    if (menuToggle && mainNav) {
        menuToggle.addEventListener('click', () => {
            const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
            menuToggle.setAttribute('aria-expanded', !isExpanded);
            mainNav.classList.toggle('active');
        });
    }

    // Wishlist toggle example (accessible focus and state)
    const wishlistBtns = document.querySelectorAll('.add-to-wishlist');
    wishlistBtns.forEach(btn => {
        btn.addEventListener('click', (e) => {
            // Prevent the product card link from firing if it overlays
            e.preventDefault();
            e.stopPropagation();

            const isPressed = btn.getAttribute('aria-pressed') === 'true';
            btn.setAttribute('aria-pressed', !isPressed);

            // Toggle icon visual state
            const svg = btn.querySelector('svg');
            if (!isPressed) {
                svg.setAttribute('fill', 'currentColor');
                svg.style.color = 'var(--color-accent)';
            } else {
                svg.setAttribute('fill', 'none');
                svg.style.color = 'currentColor';
            }
        });
    });

    // Form submission mock
    const newsletterForm = document.querySelector('.newsletter-form');
    if (newsletterForm) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const input = document.getElementById('email-input');
            const originalPlaceholder = input.placeholder;

            input.value = '';
            input.placeholder = 'Thanks for subscribing!';

            // Announce to screen readers
            const liveRegion = document.createElement('div');
            liveRegion.setAttribute('aria-live', 'polite');
            liveRegion.classList.add('sr-only');
            liveRegion.textContent = 'Successfully subscribed to newsletter.';
            document.body.appendChild(liveRegion);

            setTimeout(() => {
                input.placeholder = originalPlaceholder;
                liveRegion.remove();
            }, 3000);
        });
    }
});

