    align-items: center;
    border: 1px solid var(--color-border);
    border-radius: 20px;
    padding: 0.25rem 0.5rem 0.25rem 1rem;
}

.search-form input {
    border: none;
    outline: none;
    padding: 0.25rem;
    font-family: inherit;
    width: 150px;
    background: transparent;
}

.search-form button {
