    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: var(--spacing-2xl);
}

.product-card {
    display: flex;
    flex-direction: column;
    position: relative;
}

.product-image {
    position: relative;
    aspect-ratio: 4/5;
    background: var(--color-surface);
    margin-bottom: var(--spacing-md);
    border-radius: var(--border-radius);
    overflow: hidden;
}

.product-image img {
    width: 100%;
    height: 100%;
