    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .newsletter-container {
        grid-template-columns: 1fr;
        text-align: center;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }

    .footer-nav {
        grid-template-columns: 1fr;
    }

    .footer-bottom {
        flex-direction: column;
        gap: var(--spacing-md);
        text-align: center;
    }
}
